const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.BBox(58.5, 24.5, 63.5, 30.0); // Approximate bounding box for Sistan-Baluchestan Province, Iran
  const startDate = '2020-01-08';
  const endDate = '2020-01-15';
  const thresholdInches = 3;
  const mmPerInch = 25.4;
  const thresholdMm = thresholdInches * mmPerInch; // Convert 3 inches to millimeters

  // 2. Data Acquisition & Check
  let chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(geometry);

  const imageCount = await chirps.size().getInfo();

  if (imageCount === 0) {
    console.log(`No CHIRPS images found for the period ${startDate} to ${endDate}.`);
    console.log("C1"); // Empty Collection
    return;
  }

  // Calculate total rainfall over the period
  // The 'precipitation' band contains daily rainfall in mm
  const totalRainfallImage = chirps.select('precipitation').sum();

  // 3. Processing (Calculate pixel count to detect C2)
  // Use a coarse scale to avoid memory issues and speed up reduction.
  const scale = 5000; // CHIRPS resolution is ~5km, so 5km scale is appropriate

  const pixelCount = await totalRainfallImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  if (pixelCount === 0) {
    console.log("No valid pixels remain after filtering for the specified geometry.");
    console.log("C2"); // No Valid Pixels
    return;
  }

  // 4. Calculation
  const meanRainfallMm = await totalRainfallImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 5. Validation & Final Answer
  if (meanRainfallMm === null || isNaN(meanRainfallMm)) {
    console.log("Calculation of mean rainfall failed (result is null or NaN).");
    console.log("C3"); // Calculation Failure
    return;
  }

  const meanRainfallInches = meanRainfallMm / mmPerInch;

  console.log(`CHIRPS Images found: ${imageCount}`);
  console.log(`Valid pixels in region: ${pixelCount}`);
  console.log(`Total average rainfall (mm): ${meanRainfallMm.toFixed(2)}`);
  console.log(`Total average rainfall (inches): ${meanRainfallInches.toFixed(2)}`);
  console.log(`Threshold: ${thresholdInches} inches (${thresholdMm.toFixed(2)} mm)`);

  if (meanRainfallInches > thresholdInches) {
    console.log("A"); // Yes, experienced over 3 inches
  } else {
    console.log("B"); // No, did not experience over 3 inches
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
